create extension if not exists pgcrypto;
create table if not exists vehicles(id uuid primary key default gen_random_uuid(),plate_number text unique not null,active boolean not null default true,created_at timestamptz default now());
create table if not exists users(id uuid primary key default gen_random_uuid(),name text unique not null,active boolean not null default true,created_at timestamptz default now());
create table if not exists locations(id uuid primary key default gen_random_uuid(),name text unique not null,active boolean not null default true,created_at timestamptz default now());
create table if not exists usage_records(id uuid primary key default gen_random_uuid(),vehicle_id uuid not null references vehicles(id),usage_date date not null,user_id uuid references users(id),custom_user_name text,start_location_id uuid references locations(id),start_location_custom text,end_location_id uuid references locations(id),end_location_custom text,start_time time not null,end_time time not null,start_mileage numeric not null,end_mileage numeric not null,remark text,created_by uuid,created_at timestamptz default now(),check(end_time>=start_time),check(end_mileage>=start_mileage));
create table if not exists usage_record_purposes(id uuid primary key default gen_random_uuid(),usage_record_id uuid not null references usage_records(id) on delete cascade,purpose_name text not null);
create table if not exists trip_stops(id uuid primary key default gen_random_uuid(),usage_record_id uuid not null references usage_records(id) on delete cascade,location_id uuid references locations(id),custom_location text,stop_time time,sequence int not null);
create table if not exists fuel_records(id uuid primary key default gen_random_uuid(),vehicle_id uuid not null references vehicles(id),usage_record_id uuid references usage_records(id) on delete set null,fuel_date date not null,mileage numeric,amount numeric not null default 0,remark text,created_at timestamptz default now());
